div.script:

document.title = "dormo.io";

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// 3D Engine Constants
const fov = 350; // Field of view depth
const cx = canvas.width / 2;
const cy = canvas.height / 2 + 50;

let player = {
  x: 0,   // 3D World X
  z: 0,   // 3D World Z (Depth)
  dx: 1.5,
  dz: 0,
  radius: 12,
  trail: []
};

let score = 0;

window.addEventListener('keydown', e => {
  if ((e.key === 'ArrowUp' || e.key === 'w') && player.dz === 0) { player.dx = 0; player.dz = -1.5; }
  if ((e.key === 'ArrowDown' || e.key === 's') && player.dz === 0) { player.dx = 0; player.dz = 1.5; }
  if ((e.key === 'ArrowLeft' || e.key === 'a') && player.dx === 0) { player.dx = -1.5; player.dz = 0; }
  if ((e.key === 'ArrowRight' || e.key === 'd') && player.dx === 0) { player.dx = 1.5; player.dz = 0; }
});

function project(x, y, z) {
  // Perspective projection calculation
  const scale = fov / (fov + z);
  return {
    x: cx + x * scale,
    y: cy + y * scale,
    scale: scale
  };
}

function update() {
  player.x += player.dx;
  player.z += player.dz;

  // Boundary limits in 3D world space
  if (player.x < -180) player.x = 180;
  if (player.x > 180) player.x = -180;
  if (player.z < -180) player.z = 180;
  if (player.z > 180) player.z = -180;

  // Push trail points in 3D
  if (Math.random() < 0.25) {
    player.trail.push({x: player.x, z: player.z});
    if (player.trail.length > 120) player.trail.shift();
    score = Math.min(100, Math.floor(player.trail.length * 0.8));
    document.getElementById('scoreDisplay').textContent = "3D Territory Captured: " + score + "%";
  }
}

function drawGrid3D() {
  // Draw 3D floor grid lines moving into perspective
  ctx.strokeStyle = '#1e293b';
  ctx.lineWidth = 1.5;

  const step = 30;
  const limit = 180;

  for (let i = -limit; i <= limit; i += step) {
    // Vertical grid lines (Z-axis depth)
    let p1 = project(i, 0, -limit);
    let p2 = project(i, 0, limit);
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.stroke();

    // Horizontal grid lines (X-axis width)
    let p3 = project(-limit, 0, i);
    let p4 = project(limit, 0, i);
    ctx.beginPath();
    ctx.moveTo(p3.x, p3.y);
    ctx.lineTo(p4.x, p4.y);
    ctx.stroke();
  }
}

function draw() {
  // Clear screen
  ctx.fillStyle = '#0b0f19';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Render 3D Grid floor
  drawGrid3D();

  // Draw trail in 3D space
  player.trail.forEach((t, idx) => {
    const p = project(t.x, 0, t.z);
    if (p.scale > 0) {
      ctx.fillStyle = '#f97316';
      ctx.beginPath();
      ctx.arc(p.x, p.y, 6 * p.scale, 0, Math.PI * 2);
      ctx.fill();
    }
  });

  // Draw Player in 3D (Orange Smiley 3D Disc)
  const p = project(player.x, -5, player.z);
  if (p.scale > 0) {
    const r = player.radius * p.scale;

    // Outer orange sphere/disc body
    ctx.fillStyle = '#f97316';
    ctx.beginPath();
    ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#ea580c';
    ctx.lineWidth = 2 * p.scale;
    ctx.stroke();

    // Eyes & Smile projected onto 3D face
    const eyeSize = Math.max(1.5, 3 * p.scale);
    ctx.fillStyle = '#7c2d12';
    ctx.fillRect(p.x - 5 * p.scale, p.y - 4 * p.scale, eyeSize, eyeSize);
    ctx.fillRect(p.x + 3 * p.scale, p.y - 4 * p.scale, eyeSize, eyeSize);

    ctx.strokeStyle = '#7c2d12';
    ctx.lineWidth = 1.5 * p.scale;
    ctx.beginPath();
    ctx.arc(p.x, p.y + 2 * p.scale, 4 * p.scale, 0, Math.PI, false);
    ctx.stroke();
  }
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();
